def transform(grid):
    h, w = len(grid), len(grid[0])
    # Uniform separator lines use a color other than the repeated tile background.
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    sep_candidates = Counter()
    for r, row in enumerate(grid):
        if len(set(row)) == 1 and row[0] != background:
            sep_candidates[row[0]] += 1
    for c in range(w):
        vals = {grid[r][c] for r in range(h)}
        if len(vals) == 1:
            color = next(iter(vals))
            if color != background:
                sep_candidates[color] += 1
    sep = sep_candidates.most_common(1)[0][0] if sep_candidates else None
    sep_rows = {r for r in range(h) if sep is not None and all(v == sep for v in grid[r])}
    sep_cols = {c for c in range(w) if sep is not None and all(grid[r][c] == sep for r in range(h))}

    def spans(n, cuts):
        out, start = [], 0
        for i in range(n):
            if i in cuts:
                if start < i:
                    out.append((start, i))
                start = i + 1
        if start < n:
            out.append((start, n))
        return out

    row_spans, col_spans = spans(h, sep_rows), spans(w, sep_cols)
    if not row_spans or not col_spans:
        return [row[:] for row in grid]
    tile_h, tile_w = row_spans[0][1] - row_spans[0][0], col_spans[0][1] - col_spans[0][0]
    # Learn the non-background motif in tile-local coordinates, then repeat it
    # in every compartment of the same size.
    motif = {}
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if r1 - r0 != tile_h or c1 - c0 != tile_w:
                continue
            for dr in range(tile_h):
                for dc in range(tile_w):
                    value = grid[r0 + dr][c0 + dc]
                    if value != background:
                        motif[(dr, dc)] = value
    result = [row[:] for row in grid]
    for r0, r1 in row_spans:
        for c0, c1 in col_spans:
            if r1 - r0 != tile_h or c1 - c0 != tile_w:
                continue
            for (dr, dc), value in motif.items():
                result[r0 + dr][c0 + dc] = value
    return result


